.progress:has(> .determinate, > .indeterminate),
.progress.progress-material {
  --dx-preloader-color: var(--dx-teal, #008080);
  position: relative;
  display: block;
  height: 4px;
  width: 100%;
  background-color: color-mix(in srgb, var(--dx-preloader-color) 22%, transparent);
  border-radius: 2px;
  margin: 0.5rem 0 1rem;
  overflow: hidden;
}

.progress .determinate {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  background-color: var(--dx-preloader-color, var(--dx-teal, #008080));
  transition: width 0.3s linear;
}

.progress .indeterminate {
  background-color: var(--dx-preloader-color, var(--dx-teal, #008080));
}
.progress .indeterminate::before, .progress .indeterminate::after {
  content: "";
  position: absolute;
  background-color: inherit;
  top: 0;
  left: 0;
  bottom: 0;
  will-change: left, right;
