.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  padding: 0;
  margin-bottom: 1rem;
  list-style: none;
  font-size: 0.9rem;
}

.breadcrumb-item {
  display: inline-flex;
  align-items: center;
}
.breadcrumb-item a {
  color: var(--dx-primary, #3b5998);
  text-decoration: none;
}
.breadcrumb-item a:hover {
  text-decoration: underline;
}
.breadcrumb-item + .breadcrumb-item {
  padding-inline-start: 0.5rem;
}
.breadcrumb-item + .breadcrumb-item::before {
  display: inline-block;
  padding-inline-end: 0.5rem;
  color: var(--dx-text-muted, #64748b);
  content: var(--dx-breadcrumb-divider, "/");
}
.breadcrumb-item.active {
  color: var(--dx-text-muted, #64748b);
  font-weight: 500;
}

.progress,
.progress-stacked {
  display: flex;
  height: var(--dx-progress-height);
  overflow: hidden;
  font-size: 0.75rem;
  background-color: var(--dx-progress-bg);
  border-radius: var(--dx-radius-md, 0.375rem);
}

