.avatar-status,
.avatar-indicator {
  position: absolute;
  display: block;
  width: calc(var(--dx-avatar-size) * 0.28);
  height: calc(var(--dx-avatar-size) * 0.28);
  min-width: 0.5rem;
  min-height: 0.5rem;
  max-width: 1.5rem;
  max-height: 1.5rem;
  border-radius: 50%;
  border: var(--dx-avatar-border-width, 2px) solid var(--dx-body-bg, #ffffff);
  box-sizing: content-box;
  z-index: 2;
  top: 2%;
  right: 2%;
}
.avatar-status.status-bottom-right, .avatar-status.status-bottom,
.avatar-indicator.status-bottom-right,
.avatar-indicator.status-bottom {
  top: auto;
  bottom: 2%;
  right: 2%;
}
.avatar-status.status-bottom-left,
.avatar-indicator.status-bottom-left {
  top: auto;
  bottom: 2%;
  right: auto;
  left: 2%;
}
.avatar-status.status-top-left,
.avatar-indicator.status-top-left {
  top: 2%;
  right: auto;
  left: 2%;
}
.avatar-status.status-online, .avatar-status.status-success,
.avatar-indicator.status-online,
.avatar-indicator.status-success {
  background-color: #22c55e;
}
.avatar-status.status-busy, .avatar-status.status-danger,
.avatar-indicator.status-busy,
.avatar-indicator.status-danger {
  background-color: #ef4444;
}
.avatar-status.status-away, .avatar-status.status-warning,
.avatar-indicator.status-away,
.avatar-indicator.status-warning {
  background-color: #f59e0b;
}
.avatar-status.status-offline, .avatar-status.status-secondary,
.avatar-indicator.status-offline,
.avatar-indicator.status-secondary {
  background-color: #94a3b8;
}
.avatar-status.status-dnd,
.avatar-indicator.status-dnd {
  background-color: #ef4444;
}
.avatar-status.status-dnd::after,
.avatar-indicator.status-dnd::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 20%;
  right: 20%;
  height: 2px;
  background-color: #ffffff;
  transform: translateY(-50%);
}
.avatar-status.status-pulse::before,
.avatar-indicator.status-pulse::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background-color: inherit;
  opacity: 0.75;
  animation: avatar-status-pulse 1.8s cubic-bezier(0.24, 0, 0.38, 1) infinite;
  z-index: -1;
}

@keyframes avatar-status-pulse {
  0% {
    transform: scale(0.95);
    opacity: 0.8;
  }
  70% {
    transform: scale(2.2);
    opacity: 0;
  }
  100% {
    transform: scale(2.2);
    opacity: 0;
  }
}
