:root {
  --dx-fileinput-bg: #f8fafc;
  --dx-fileinput-border: #cbd5e1;
  --dx-fileinput-border-hover: var(--dx-primary, #3b5998);
  --dx-fileinput-bg-hover: #edf2fa;
  --dx-fileinput-thumb-bg: #ffffff;
  --dx-fileinput-thumb-border: #e2e8f0;
  --dx-fileinput-text: #1e293b;
  --dx-fileinput-muted: #64748b;
  --dx-fileinput-radius: var(--dx-radius-lg, 0.5rem);
}

[data-dx-theme=dark] {
  --dx-fileinput-bg: #0f172a;
  --dx-fileinput-border: #334155;
  --dx-fileinput-border-hover: var(--dx-primary, #4c6ef5);
  --dx-fileinput-bg-hover: #1e293b;
  --dx-fileinput-thumb-bg: #1e293b;
  --dx-fileinput-thumb-border: #334155;
  --dx-fileinput-text: #f1f5f9;
  --dx-fileinput-muted: #94a3b8;
}

.file-input-native-hidden {
  position: absolute !important;
  width: 0.1px !important;
  height: 0.1px !important;
  opacity: 0 !important;
  overflow: hidden !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

.file-input-wrapper {
  position: relative;
  display: block;
  width: 100%;
  font-family: inherit;
  box-sizing: border-box;
}
.file-input-wrapper.is-disabled {
  opacity: 0.6;
  pointer-events: none;
}

.file-drop-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  padding: 2.25rem 1.5rem;
  text-align: center;
  cursor: pointer;
  background-color: var(--dx-fileinput-bg);
  border: 2px dashed var(--dx-fileinput-border);
  border-radius: var(--dx-fileinput-radius);
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  user-select: none;
}
.file-drop-zone:hover, .file-drop-zone.is-dragover {
  border-color: var(--dx-fileinput-border-hover);
  background-color: var(--dx-fileinput-bg-hover);
  transform: translateY(-2px);
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.08);
}
.file-drop-zone:hover .file-drop-icon, .file-drop-zone.is-dragover .file-drop-icon {
  transform: translateY(-4px) scale(1.08);
  color: var(--dx-primary, #3b5998);
}
.file-drop-zone.is-dragover {
  border-style: solid;
  border-width: 2px;
}
.file-drop-zone .file-drop-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  margin-bottom: 1rem;
  color: var(--dx-primary, #3b5998);
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), color 0.2s ease;
}
.file-drop-zone .file-drop-icon svg {
  width: 100%;
  height: 100%;
  stroke-width: 1.75;
}
.file-drop-zone .file-drop-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--dx-fileinput-text);
  margin-bottom: 0.35rem;
}
.file-drop-zone .file-drop-title .file-browse-link {
  color: var(--dx-primary, #3b5998);
  text-decoration: underline;
  cursor: pointer;
}
.file-drop-zone .file-drop-subtitle {
  font-size: 0.875rem;
  color: var(--dx-fileinput-muted);
  margin-bottom: 1rem;
  max-width: 480px;
}
.file-drop-zone .file-drop-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
}
.file-drop-zone .file-drop-tags .file-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 0.25rem;
  background-color: rgba(203, 213, 225, 0.4);
  color: var(--dx-fileinput-text);
  letter-spacing: 0.02em;
