/* ==========================================================================
   Avaliação por Estrelas / Star Rating
   ========================================================================== */
:root {
  --dx-rating-empty-color: #cbd5e1;
  --dx-rating-filled-color: var(--dx-gold, #f59e0b);
  --dx-rating-hover-color: var(--dx-gold-600, #d97706);
  --dx-rating-gap: 0.25rem;
  --dx-rating-size-xs: 0.875rem;
  --dx-rating-size-sm: 1.125rem;
  --dx-rating-size-md: 1.5rem;
  --dx-rating-size-lg: 2rem;
  --dx-rating-size-xl: 2.75rem;
  --dx-rating-size: var(--dx-rating-size-md);
}

[data-dx-theme=dark] {
  --dx-rating-empty-color: #333948;
  --dx-rating-filled-color: var(--dx-gold, #f59e0b);
  --dx-rating-hover-color: #fbbf24;
}

.rating-container,
.dx-rating {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  vertical-align: middle;
  font-family: var(--dx-font-body);
  user-select: none;
}
.rating-container.rating-disabled,
.dx-rating.rating-disabled {
  opacity: 0.6;
  pointer-events: none;
  cursor: not-allowed;
}
.rating-container.rating-readonly,
.dx-rating.rating-readonly {
  cursor: default;
}
.rating-container.rating-readonly .rating-stars,
.dx-rating.rating-readonly .rating-stars {
  cursor: default;
}
.rating-container.rating-readonly .rating-clear,
.dx-rating.rating-readonly .rating-clear {
  display: none !important;
}

.rating-stars {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  line-height: 1;
}
.rating-stars:focus-visible {
  outline: 2px solid var(--dx-primary, #3b5998);
  outline-offset: 3px;
  border-radius: var(--dx-radius-sm, 0.25rem);
}

.rating-empty {
  display: flex;
  align-items: center;
  gap: var(--dx-rating-gap);
  color: var(--dx-rating-empty-color);
  transition: color 150ms ease;
}

.rating-filled {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  display: flex;
  align-items: center;
  gap: var(--dx-rating-gap);
  overflow: hidden;
  white-space: nowrap;
  color: var(--dx-rating-filled-color);
  transition: width 100ms ease-out, color 150ms ease;
  pointer-events: none;
}

.rating-star {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--dx-rating-size);
  height: var(--dx-rating-size);
  flex-shrink: 0;
  transition: transform 120ms ease;
}
.rating-star svg {
  width: 100%;
  height: 100%;
  fill: currentColor;
  display: block;
}
.rating-stars:hover .rating-star {
  transform: scale(1.05);
}

.rating-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
  border: none;
  background: transparent;
  color: #94a3b8;
  cursor: pointer;
  border-radius: 50%;
  transition: color 150ms ease, background-color 150ms ease, transform 150ms ease;
}
.rating-clear svg {
  width: 0.875rem;
  height: 0.875rem;
  fill: currentColor;
}
.rating-clear:hover {
  color: var(--dx-red, #ef4444);
  background-color: rgba(239, 68, 68, 0.1);
  transform: scale(1.1);
}
.rating-clear:active {
  transform: scale(0.92);
}

