   ========================================================================== */
:root {
  --dx-multiselect-bg: var(--dx-form-input-bg, #ffffff);
  --dx-multiselect-color: var(--dx-form-input-color, #1e293b);
  --dx-multiselect-border: var(--dx-form-input-border, #cbd5e1);
  --dx-multiselect-border-hover: #94a3b8;
  --dx-multiselect-focus-border: var(--dx-primary, #3b5998);
  --dx-multiselect-radius: var(--dx-radius-md, 0.375rem);
  --dx-multiselect-min-height: 2.375rem;
  --dx-multiselect-menu-bg: #ffffff;
  --dx-multiselect-menu-border: rgba(0, 0, 0, 0.12);
  --dx-multiselect-menu-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.12), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
  --dx-multiselect-hover-bg: #f8fafc;
  --dx-multiselect-active-bg: #edf2fa;
  --dx-multiselect-active-color: var(--dx-primary, #3b5998);
}

[data-dx-theme=dark] {
  --dx-multiselect-bg: #1e222d;
  --dx-multiselect-color: #f1f5f9;
  --dx-multiselect-border: #333948;
  --dx-multiselect-border-hover: #4b5563;
  --dx-multiselect-focus-border: var(--dx-primary, #3b5998);
  --dx-multiselect-menu-bg: #1e222d;
  --dx-multiselect-menu-border: #333948;
  --dx-multiselect-menu-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.45);
  --dx-multiselect-hover-bg: #272d3b;
  --dx-multiselect-active-bg: #2b3648;
  --dx-multiselect-active-color: #60a5fa;
}

.dx-multiselect,
.bs-multiselect {
  position: relative;
  width: 100%;
  font-family: var(--dx-font-body);
}
.dx-multiselect.is-disabled,
.bs-multiselect.is-disabled {
  opacity: 0.65;
  pointer-events: none;
  cursor: not-allowed;
}

.multiselect-toggle {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.375rem;
  width: 100%;
  min-height: var(--dx-multiselect-min-height);
  padding: 0.3125rem 2.25rem 0.3125rem 0.625rem;
  font-size: var(--dx-form-input-font-size, 0.875rem);
  color: var(--dx-multiselect-color);
  background-color: var(--dx-multiselect-bg);
  background-clip: padding-box;
  border: 1px solid var(--dx-multiselect-border);
  border-radius: var(--dx-multiselect-radius);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.075);
  cursor: pointer;
  position: relative;
  user-select: none;
  transition: border-color 200ms ease-in-out, box-shadow 200ms ease-in-out, background-color 200ms ease-in-out;
}
.multiselect-toggle:hover {
  border-color: var(--dx-multiselect-border-hover);
}
.dx-multiselect.is-open .multiselect-toggle, .multiselect-toggle:focus-visible {
  border-color: var(--dx-multiselect-focus-border);
  outline: none;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.075), 0 0 8px color-mix(in srgb, var(--dx-multiselect-focus-border) 45%, transparent);
}
.multiselect-toggle::after {
  content: "";
  position: absolute;
  right: 0.875rem;
  top: 50%;
  width: 0.5rem;
  height: 0.5rem;
  border: solid currentColor;
  border-width: 0 2px 2px 0;
  transform: translateY(-70%) rotate(45deg);
  opacity: 0.6;
  pointer-events: none;
  transition: transform 200ms ease, opacity 200ms ease;
}
.dx-multiselect.is-open .multiselect-toggle::after {
  transform: translateY(-30%) rotate(-135deg);
  opacity: 1;
}

.multiselect-placeholder {
  color: #94a3b8;
  font-size: inherit;
  line-height: 1.4;
}

.multiselect-summary {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-weight: 500;
  color: var(--dx-multiselect-color);
}
