/* ==========================================================================
   Alertify (Diálogos, Notificador e Factory) / Alertify Dialogs, Notifier & Factory
   ========================================================================== */
.alertify {
  --dx-ajs-bg: #ffffff;
  --dx-ajs-color: #1e293b;
  --dx-ajs-muted: #64748b;
  --dx-ajs-border: rgba(15, 23, 42, 0.12);
  --dx-ajs-footer-bg: #f8fafc;
  --dx-ajs-input-bg: #ffffff;
  --dx-ajs-input-border: #cbd5e1;
  --dx-ajs-accent: var(--dx-primary, #3b5998);
  --dx-ajs-accent-fg: #ffffff;
  --dx-ajs-shadow: 0 24px 60px -12px rgba(15, 23, 42, 0.35);
  position: fixed;
  inset: 0;
  z-index: 1096;
  pointer-events: none;
}
.alertify.ajs-hidden {
  display: none;
}
.alertify .ajs-dimmer {
  position: fixed;
  inset: 0;
  background-color: rgba(15, 23, 42, 0.56);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: auto;
  transition: opacity 0.22s ease;
}
.alertify.ajs-no-dimmer .ajs-dimmer {
  display: none;
}
.alertify .ajs-modal {
  position: fixed;
  inset: 0;
  overflow-y: auto;
  display: flex;
